import {Chess} from './chess.js';
const initial=Object.fromEntries(new Chess().board().flat().filter(Boolean).map(p=>[p.square,p.color==='w'?p.type.toUpperCase():p.type]));
const make=(id,pieces,answers,taskTitle,prompt,hint,explanation)=>({id,pieces,answers,taskTitle,prompt,hint,explanation,introduction:prompt,positionKind:'boardStudy',goal:'square',familyId:'board-foundations',skillId:id.startsWith('orientation-')?'board-orientation':'starting-position',syncGroup:'board-v1'});
export const BOARD_EXERCISES=[
 make('orientation-white-right',{},['h1'],'Светлый угол у белых','Белые находятся снизу. Доску ставят светлой угловой клеткой справа от белых: здесь это h1.','Ищи нижний правый угол.','Справа рядом с белыми — светлая клетка h1.'),
 make('orientation-white-left',{},['a1'],'Тёмный угол у белых','Нажми на тёмную угловую клетку слева от белых. Белые находятся снизу.','Ищи нижний левый угол.','Слева рядом с белыми — тёмная клетка a1.'),
 make('orientation-black-right',{},['a8'],'Светлый угол у чёрных','Чёрные находятся сверху и смотрят к белым. Нажми на светлый угол справа от чёрных.','Справа от чёрных — слева на нашем экране, вверху.','Справа от чёрных — светлая клетка a8. Она слева вверху на нашем экране.'),
 make('orientation-black-left',{},['h8'],'Тёмный угол у чёрных','Нажми на тёмный угол слева от чёрных. Чёрные находятся сверху.','Слева от чёрных — справа на экране, вверху.','Слева от чёрных — тёмная клетка h8.'),
 make('setup-rooks',initial,['a1','h1','a8','h8'],'Ладьи стоят в углах','Это вся начальная расстановка. Найди любую ладью в углу доски.','У каждого игрока две ладьи — в крайних углах своего ряда.','Ладьи стоят по углам: a1, h1, a8 и h8.'),
 make('setup-knights',initial,['b1','g1','b8','g8'],'Кони рядом с ладьями','Нажми на любого коня в начальной расстановке.','От угла к середине: ладья, затем конь.','Кони стоят рядом с ладьями: b1, g1, b8 и g8.'),
 make('setup-bishops',initial,['c1','f1','c8','f8'],'Слоны рядом с конями','Нажми на любого слона в начальной расстановке.','От угла к середине: ладья, конь, затем слон.','Слоны стоят рядом с конями: c1, f1, c8 и f8.'),
 make('setup-pawns',initial,[...'abcdefgh'].flatMap(f=>[f+'2',f+'7']),'Пешки перед фигурами','Нажми на любую пешку в начальной расстановке.','Восемь белых пешек — на втором ряду, восемь чёрных — на седьмом.','Пешки стоят рядами перед остальными фигурами: белые на втором, чёрные на седьмом.'),
 make('setup-white-queen',initial,['d1'],'Белый ферзь на светлом','Ферзь начинает на клетке своего цвета. Белый ферзь — на светлой d1. Посмотрим на него.','У белых ферзь на d1, король справа от него на e1.','Белый ферзь стоит на светлой клетке d1.'),
 make('setup-black-queen',initial,['d8'],'Чёрный ферзь на тёмном','Найди чёрного ферзя на клетке его цвета.','Чёрный ферзь стоит на тёмной d8 напротив белого ферзя.','Чёрный ферзь стоит на тёмной клетке d8. Ферзи начинают напротив друг друга.'),
 make('setup-white-king',initial,['e1'],'Белый король рядом с ферзём','Нажми на белого короля в начальной расстановке.','Белый король стоит на e1, рядом с белым ферзём d1.','Белый король стоит на e1, рядом с ферзём.'),
 make('setup-black-king',initial,['e8'],'Чёрный король рядом с ферзём','Нажми на чёрного короля в начальной расстановке.','Чёрный король стоит на e8 напротив белого короля e1.','Чёрный король стоит на e8. Теперь ты рассмотрел места всех фигур в начальной расстановке.')
];
const placements=[
 ['place-white-rook','a1','R','Поставь белую ладью','Белая ладья ждёт своего места. Нажми на пустой угол, где она стоит в начале партии.','Белые снизу. У белых ладьи стоят по углам нижнего ряда.'],
 ['place-black-knight','b8','n','Поставь чёрного коня','В начальной расстановке не хватает чёрного коня. Нажми на его пустое место рядом с ладьёй.','Чёрные сверху. От угла к середине: ладья, конь, слон.'],
 ['place-white-queen','d1','Q','Поставь белого ферзя','Белый ферзь начинает на светлой клетке. Найди его пустое место рядом с королём.','Белые снизу. Белый ферзь стоит на светлой d1, рядом с королём e1.'],
 ['place-black-king','e8','k','Поставь чёрного короля','Верни чёрного короля на пустое место рядом с чёрным ферзём.','Чёрный ферзь на d8, король рядом на e8.']
];
BOARD_EXERCISES.push(...placements.map(([id,square,placePiece,taskTitle,prompt,hint])=>{
 const pieces={...initial};delete pieces[square];
 return {...make(id,pieces,[square],taskTitle,prompt,hint,'Фигура на месте! Начальная расстановка снова полная.'),goal:'placePiece',placePiece};
}));
